import 'package:flutter/material.dart';import '../api/gaon_api.dart';import '../models/models.dart';class OrdersScreen extends StatefulWidget{const OrdersScreen({super.key});@override State<OrdersScreen> createState()=>_OrdersScreenState();}class _OrdersScreenState extends State<OrdersScreen>{List<OrderModel> orders=[];bool loading=true;String? error;String? payingOrderId;@override void initState(){super.initState();load();}Future<void> load()async{try{final d=await GaonApi.orders();if(mounted)setState((){orders=d;loading=false;error=null;});}catch(e){if(mounted)setState((){loading=false;error='$e';});}}Future<void> pay(OrderModel o)async{setState(()=>payingOrderId=o.id);try{final paid=await GaonApi.openRazorpayCheckout(o);if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(paid?'Payment confirmed.':'Payment was not completed.')));await load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>payingOrderId=null);}}Future<void> cancel(OrderModel o)async{final yes=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Cancel order?'),content:Text('${o.orderNumber} can only be cancelled before the store accepts it.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Keep order')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Cancel order'))]));if(yes==true){try{await GaonApi.cancelOrder(o.id);await load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}}Future<void> detail(OrderModel o)async{try{final d=await GaonApi.orderDetail(o.id);if(!mounted)return;final items=(d['items']as List? ??[]);showModalBottomSheet(context:context,isScrollControlled:true,builder:(c)=>SafeArea(child:Padding(padding:const EdgeInsets.all(20),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text(o.orderNumber,style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),Text('${d['store_name']??'Store'} • ${o.status.replaceAll('_',' ')}'),const Divider(),...items.map((i)=>ListTile(contentPadding:EdgeInsets.zero,title:Text(i['product_name']??'Item'),subtitle:Text('${i['quantity']} × ₹${i['unit_price']}'),trailing:Text('₹${i['line_total']}'))),const Divider(),Text('Deliver to: ${d['house_details']??''} ${d['customer_landmark']??''}'),if(d['customer_directions']!=null)Text('Directions: ${d['customer_directions']}'),const SizedBox(height:10),Align(alignment:Alignment.centerRight,child:Text('Total ₹${o.total}',style:const TextStyle(fontWeight:FontWeight.w800)))]))));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}@override Widget build(BuildContext c){if(loading)return const Center(child:CircularProgressIndicator());return RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[Text('My orders',style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w800)),const Text('Track fulfilment, review delivery details and manage eligible cancellations.'),if(error!=null)Text(error!,style:TextStyle(color:Theme.of(c).colorScheme.error)),if(orders.isEmpty)const Padding(padding:EdgeInsets.all(40),child:Center(child:Text('No orders yet.'))),...orders.map((o)=>Card(child:InkWell(onTap:()=>detail(o),child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(o.orderNumber,style:const TextStyle(fontWeight:FontWeight.w800))),Chip(label:Text(o.status.replaceAll('_',' ')))]),Text('₹${o.total} • ${o.paymentMethod.toUpperCase()} • ${o.paymentStatus}'),const SizedBox(height:8),Wrap(spacing:8,children:[OutlinedButton.icon(onPressed:()=>detail(o),icon:const Icon(Icons.receipt_long),label:const Text('Details')),if(o.status=='placed')TextButton(onPressed:()=>cancel(o),child:const Text('Cancel order')),if(o.paymentMethod=='upi'&&o.paymentStatus!='paid'&&o.status!='cancelled')FilledButton.icon(onPressed:payingOrderId==o.id?null:()=>pay(o),icon:const Icon(Icons.payments_outlined),label:Text(payingOrderId==o.id?'Opening…':'Pay now'))])]))))]));}}
